from ta_moler.cmd.netactnode.genericnetactnode import GenericNetActNodeCommand
from moler.exceptions import ParsingDone
from moler.exceptions import CommandFailure
import re


class Smanager(GenericNetActNodeCommand):
    """Smanager command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None,
                 runner=None):
        """
        Smanager command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Smanager, self).__init__(connection=connection, prompt=prompt,
                                       newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret["LINES"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "/opt/cpf/bin/smanager.pl"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise.
        :return: None.
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._search_node_number(line)
            except ParsingDone:
                pass
        return super(Smanager, self).on_new_line(line, is_full_line)

    # ERROR: Unknown command: stat
    _re_parse_error = re.compile(r'(?P<ERROR>ERROR.*)')

    def _parse_error(self, line):
        """
        Parse line if error.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches error.
        """
        if self._regex_helper.search_compiled(Smanager._re_parse_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    # rsyslog-clab1364node01    started (u)   standAlone
    _re_parse_node = re.compile(r'([_a-zA-Z0-9]+(-)*)+(:)*(clab|coop)[0-9]+node[0-9]+')

    def _search_node_number(self, line):
        """
        Parse number and full name of node.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches number and full name of node.
        """
        if self._regex_helper.search_compiled(Smanager._re_parse_node, line):
            full_node_name = self._regex_helper.group(0)
            if ':' in full_node_name:
                split_full_node_name = full_node_name.split(':')
            else:
                split_full_node_name = full_node_name.split('-')
            node_name = split_full_node_name[-1]
            remained_name_node = '-'.join(split_full_node_name[:-1])
            if node_name not in self.current_ret["LINES"]:
                self.current_ret["LINES"][node_name] = []
            self.current_ret["LINES"][node_name].append(remained_name_node)
            raise ParsingDone


